corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { s3 } = require('../aws');
const { watermarkPdf } = require('../pdf');
const { db } = require('../db');

async function consumeWatermarkQueue() {
  while (true) {
    const messages = await redis.xreadgroup('GROUP', 'watermark-group', 'w-1', 'BLOCK', 2500, 'STREAMS', 'stream:docs:watermark', '>');
    if (!messages) continue;

    for (const [, items] of messages) {
      for (const [id, data] of items) {
        const { documentKey, requesterUserId, watermarkText } = JSON.parse(data[1]);

        const auth = await db.query(
          'SELECT id FROM user_documents WHERE s3_key = $1 AND owner_id = $2',
          [documentKey, requesterUserId]
        );
        if (auth.rowCount === 0) {
          await redis.xack('stream:docs:watermark', 'watermark-group', id);
          continue;
        }

        const original = await s3.getObject({ Bucket: process.env.DOCS_BUCKET, Key: documentKey }).promise();
        const watermarkedBuffer = await watermarkPdf(original.Body, watermarkText);

        await s3.putObject({
          Bucket: process.env.USER_EXPORTS_BUCKET,
          Key: `users/${requesterUserId}/watermarked/${documentKey}`,
          Body: watermarkedBuffer
        }).promise();

        await redis.xack('stream:docs:watermark', 'watermark-group', id);
      }
    }
  }
}
